static const size_t GLYPH_COUNT = sizeof(glyphs) / sizeof(glyphs[0]);
static const size_t CLUSTER_COUNT = sizeof(clusters) / sizeof(clusters[0]);

const BanglaGlyph* getBanglaGlyph(uint32_t codepoint) {
  for (size_t i = 0; i < GLYPH_COUNT; ++i) {
    if (glyphs[i].codepoint == codepoint) return &glyphs[i];
  }
  return nullptr;
}

const BanglaClusterGlyph* getBanglaClusterGlyph(
  const uint32_t* codepoints, uint8_t length
) {
  for (size_t i = 0; i < CLUSTER_COUNT; ++i) {
    const BanglaClusterGlyph& g = clusters[i];
    if (g.length != length) continue;

    bool same = true;
    for (uint8_t j = 0; j < length; ++j) {
      if (g.codepoints[j] != codepoints[j]) {
        same = false;
        break;
      }
    }

    if (same) return &g;
  }
  return nullptr;
}
